fn cell(rows: List[Str], r: Int, c: Int) -> Str {
  return rows.get_or(r, "").slice(c, c + 1)
}

fn has_dup(cells: List[Str]) -> Bool {
  let filled = cells.filter(fn(x) => x != ".")
  return filled.unique().len() != filled.len()
}

pub fn sudoku(rows: List[Str]) -> Bool {
  if rows.len() != 9 {
    return false
  }
  for r in range(0, 9) {
    let row = rows.get_or(r, "")
    if row.len() != 9 {
      return false
    }
    for c in range(0, 9) {
      let ch = cell(rows: rows, r: r, c: c)
      if not "123456789.".contains(ch) {
        return false
      }
    }
  }
  for u in range(0, 9) {
    var rowc: List[Str] = []
    var colc: List[Str] = []
    var boxc: List[Str] = []
    for k in range(0, 9) {
      rowc = rowc.push(cell(rows: rows, r: u, c: k))
      colc = colc.push(cell(rows: rows, r: k, c: u))
      let br = 3 * (u / 3) + k / 3
      let bc = 3 * (u % 3) + k % 3
      boxc = boxc.push(cell(rows: rows, r: br, c: bc))
    }
    if has_dup(rowc) or has_dup(colc) or has_dup(boxc) {
      return false
    }
  }
  return true
}
